const int N = 7;
float h1(float n){ return fract(sin(n*127.1)*43758.5453); }

void mainImage(out vec4 fragColor, in vec2 fragCoord){
  vec2 p = (fragCoord - 0.5*iResolution.xy)/iResolution.y;
  float asp = iResolution.x/iResolution.y;
  float f = 0.0;
  vec2 g = vec2(0.0);
  for (int i = 0; i < N; i++){
    float fi = float(i);
    float s1 = h1(fi+1.0);
    float s2 = h1(fi+11.0);
    float s3 = h1(fi+23.0);
    float r = mix(0.07, 0.15, s3);
    float speed = mix(0.04, 0.08, s2);
    float cy = mix(-0.75, 0.75, fract(s1 + iTime*speed));
    float cx = (s2-0.5)*asp*0.8 + 0.05*sin(iTime*0.8 + fi*2.1);
    vec2 d = p - vec2(cx, cy);
    float d2 = dot(d,d) + 1e-4;
    float r2 = r*r;
    f += r2/d2;
    g += -2.0*r2*d/(d2*d2);
  }
  float w = max(fwidth(f), 0.02);
  float inside = smoothstep(1.0-w, 1.0+w, f);
  vec3 n = normalize(vec3(-g*0.035, 1.0));
  vec3 L = normalize(vec3(-0.5, 0.7, 0.6));
  vec3 V = vec3(0.0, 0.0, 1.0);
  vec3 H = normalize(L + V);
  float dif = max(dot(n, L), 0.0);
  float spe = pow(max(dot(n, H), 0.0), 60.0);
  float fres = pow(1.0 - max(n.z, 0.0), 2.0);
  vec3 wax = vec3(1.0, 0.22, 0.05);
  vec3 blob = wax*(0.25 + 0.75*dif) + vec3(1.0, 0.7, 0.4)*spe*0.8 + vec3(1.0, 0.4, 0.1)*fres*0.5;
  blob += vec3(0.4, 0.05, 0.0)*smoothstep(0.0, 1.0, f)*0.2;
  vec3 bgTop = vec3(0.12, 0.02, 0.04);
  vec3 bgBot = vec3(0.7, 0.25, 0.06);
  float yy = p.y + 0.5;
  vec3 bg = mix(bgBot, bgTop, smoothstep(0.0, 1.0, yy));
  vec2 q = p - vec2(0.0, -0.55);
  bg += vec3(0.4, 0.15, 0.03)*exp(-dot(q,q)*4.0);
  float halo = clamp(f*0.12, 0.0, 0.35);
  bg += vec3(0.6, 0.15, 0.04)*halo;
  vec3 col = mix(bg, blob, inside);
  col *= 1.0 - 0.35*dot(p, p);
  fragColor = vec4(col, 1.0);
}

const int N = 7;
float h1(float n){ return fract(sin(n*127.1)*43758.5453); }

void mainImage(out vec4 fragColor, in vec2 fragCoord){
  vec2 p = (fragCoord - 0.5*iResolution.xy)/iResolution.y;
  float T = iTime;
  float aa2 = 1.5/iResolution.y;

  float wv = mix(0.13, 0.2, smoothstep(0.36, -0.42, p.y));
  float wc = wv + 0.03;

  float Hf = 0.0;
  vec2 G = vec2(0.0);
  for (int i = 0; i < N; i++){
    float fi = float(i);
    float s1 = h1(fi+1.0);
    float s2 = h1(fi+11.0);
    float s3 = h1(fi+23.0);
    float s4 = h1(fi+37.0);
    float r = mix(0.035, 0.07, s3) * (1.0 + 0.08*sin(T*0.7 + fi*1.3));
    float sp = mix(0.05, 0.15, s2);
    float ph = fract(s1 + T*sp);
    float cy = mix(-0.40, 0.34, ph);
    float cx = clamp((s4-0.5)*0.2 + 0.03*sin(T*0.3 + fi*1.7), -0.1, 0.1);
    float fade = smoothstep(0.0, 0.1, ph) * (1.0 - smoothstep(0.8, 0.98, ph));
    vec2 d = p - vec2(cx, cy);
    float R = 2.2*r;
    float R2 = R*R;
    float q = dot(d,d)/R2;
    if (q < 1.0){
      float k = 1.0 - q;
      Hf += fade * k*k;
      G += fade * (-4.0*k*d/R2);
    }
  }

  float aa = max(fwidth(Hf), 0.002)*0.7;
  float wax = smoothstep(0.5-aa, 0.5+aa, Hf);
  vec3 n = normalize(vec3(-G*0.06, 1.0));

  vec3 L = normalize(vec3(-0.45, 0.6, 0.65));
  vec3 Vv = vec3(0.0, 0.0, 1.0);
  vec3 Hh = normalize(L + Vv);
  float dif = max(dot(n, L), 0.0);
  float spe = pow(max(dot(n, Hh), 0.0), 70.0);
  float fres = pow(1.0 - max(n.z, 0.0), 2.0);
  vec3 waxCol = vec3(1.0, 0.24, 0.05)*(0.2 + 0.9*dif)
              + vec3(1.0, 0.8, 0.5)*spe*0.9
              + vec3(1.0, 0.4, 0.12)*fres*0.4;
  waxCol += vec3(1.0, 0.35, 0.08)*0.15*smoothstep(0.5, 1.2, Hf);

  vec3 bg = mix(vec3(0.03, 0.008, 0.012), vec3(0.14, 0.03, 0.015), smoothstep(-0.5, 0.5, p.y));
  bg += vec3(0.5, 0.16, 0.05)*0.35*exp(-p.x*p.x*10.0 - (p.y+0.2)*(p.y+0.2)*6.0);

  float xin = 1.0 - smoothstep(wv-aa2, wv+aa2, abs(p.x));
  float yin = smoothstep(-0.42-aa2, -0.42+aa2, p.y) * (1.0 - smoothstep(0.36-aa2, 0.36+aa2, p.y));
  float inVes = xin * yin;

  vec3 col = bg;
  col = mix(col, col*0.7 + vec3(0.12, 0.04, 0.015), inVes);

  float rim = smoothstep(wv-0.012, wv-0.002, abs(p.x)) * (1.0 - smoothstep(wv-0.002, wv+0.006, abs(p.x)));
  col += vec3(0.7, 0.35, 0.18)*rim*0.25*yin;

  col = mix(col, waxCol, wax*inVes);

  float pl = -0.33 + 0.012*sin(p.x*22.0 + T*1.3) + 0.006*sin(p.x*41.0 - T*2.1);
  float poolM = xin * (1.0 - smoothstep(pl-aa2, pl+aa2, p.y)) * yin;
  vec3 poolCol = vec3(1.0, 0.22, 0.05)*(0.45 + 0.35*smoothstep(-0.42, -0.3, p.y));
  float edgeH = exp(-abs(p.y - pl)/0.008) * xin;
  poolCol += vec3(1.0, 0.7, 0.4)*0.6*edgeH;
  col = mix(col, poolCol, poolM);

  float wcx = 1.0 - smoothstep(wc-aa2, wc+aa2, abs(p.x));
  float capTop = wcx * smoothstep(0.36-aa2, 0.36+aa2, p.y) * (1.0 - smoothstep(0.44-aa2, 0.44+aa2, p.y));
  float capBot = wcx * (1.0 - smoothstep(-0.42-aa2, -0.42+aa2, p.y)) * smoothstep(-0.5-aa2, -0.5+aa2, p.y);
  float cap = max(capTop, capBot);
  vec3 capCol = vec3(0.12, 0.07, 0.04)*(0.6 + 0.6*(1.0 - abs(p.x)/wc));
  col = mix(col, capCol, cap);

  col *= 1.0 - 0.3*dot(p, p);
  fragColor = vec4(col, 1.0);
}
